public static void updateGUPMarginComponentAdjustmentHistory(RefRecId _retailPeriodicDiscountLineRefRecId, DiscAmount _amount, RetailDiscountOfferLineDiscMethodBase _discountMethod, SalesLine _salesLine)
{
    RetailPeriodicDiscount  periodicDiscount;
    RetailPeriodicDiscountLine periodicDiscountLine;
    GUPPriceComponentCodeSetup marginComponentSetup;

    select firstonly marginComponentSetup
        order by marginComponentSetup.CalculationSequence
        join periodicDiscount
            where marginComponentSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName
        join periodicDiscountLine
        where periodicDiscount.OfferId              == periodicDiscountLine.OfferId &&
              periodicDiscountLine.recId            == _retailPeriodicDiscountLineRefRecId &&
              periodicDiscount.Status               == RetailDisabledEnabled::Enabled &&
              periodicDiscount.IsGupDiscount        == NoYes::Yes &&
              periodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::Promotion &&
              periodicDiscount.PriceComponentType   == GUPPriceComponent::PriceMarginComponentAdjustment;

    if (periodicDiscount)
    {
        GUPMarginComponentAdjustmentHistory marginComponentAdjustmentHistory;

        marginComponentAdjustmentHistory.clear();
        marginComponentAdjustmentHistory.InventTransId = _salesLine.InventTransId;
        marginComponentAdjustmentHistory.MarginComponentCode = periodicDiscount.PriceComponentCodeName;
        marginComponentAdjustmentHistory.marginComponentAdjustment = periodicDiscount.OfferId;
        marginComponentAdjustmentHistory.CalculationSequence = marginComponentSetup.CalculationSequence;
        marginComponentAdjustmentHistory.Amount = _amount;
        marginComponentAdjustmentHistory.UnitId = UnitOfMeasure::find(periodicDiscountLine.UnitOfMeasure).Symbol;
        marginComponentAdjustmentHistory.LineNum = periodicDiscountLine.LineNum;
        marginComponentAdjustmentHistory.DiscountMethod =_discountMethod;

        RetailDiscountLineOffer discountLineOffer = periodicDiscountLine as RetailDiscountLineOffer;
        switch (marginComponentAdjustmentHistory.DiscountMethod)
        {
            case RetailDiscountOfferLineDiscMethodBase::AmountOff:
                marginComponentAdjustmentHistory.Value = discountLineOffer.discAmount;
                break;

            case RetailDiscountOfferLineDiscMethodBase::PercentOff:
                marginComponentAdjustmentHistory.Value = discountLineOffer.discPct;
                break;
        }

        marginComponentAdjustmentHistory.insert();
    }
}

public static void findOrCreateMCRPriceHistory(GUPSalesBasePriceLineMap _basePriceLineMap, SalesLine _salesLine)
{
    MCRPriceHistory     mcrPriceHistory;
    Version version;

    // Find the latest version of price history for the table and record.
    select firstonly mcrPriceHistory order by Version desc
        where mcrPriceHistory.RefRecId      == _basePriceLineMap.RefRecId
           && mcrPriceHistory.RefTableId    == _basePriceLineMap.RefTableId;

    if (!mcrPriceHistory || !mcrPriceHistory.equalBasePriceLineMap(_basePriceLineMap))
    {
        version = mcrPriceHistory.Version + 1;

        mcrPriceHistory.clear();
        mcrPriceHistory.Version = version;

        mcrPriceHistory.RefTableId             = _basePriceLineMap.RefTableId;
        mcrPriceHistory.RefRecId               = _basePriceLineMap.RefRecId;
        mcrPriceHistory.Amount                 = _basePriceLineMap.Amount;
        mcrPriceHistory.AccountCode            = _basePriceLineMap.AccountCode;
        mcrPriceHistory.AccountRelation        = _basePriceLineMap.AccountRelation;
        mcrPriceHistory.ItemCode               = _basePriceLineMap.ItemCode;
        mcrPriceHistory.ItemRelation           = _basePriceLineMap.ItemRelation;
        mcrPriceHistory.Currency               = _basePriceLineMap.Currency;
        mcrPriceHistory.FromDate               = _basePriceLineMap.FromDate;
        mcrPriceHistory.InventDimId            = _basePriceLineMap.InventDimId;
        mcrPriceHistory.Markup                 = _basePriceLineMap.Markup;
        mcrPriceHistory.AllocateMarkup         = _basePriceLineMap.AllocateMarkup;
        mcrPriceHistory.Module                 = _basePriceLineMap.Module;
        mcrPriceHistory.Percent1               = _basePriceLineMap.Percent1;
        mcrPriceHistory.Percent2               = _basePriceLineMap.Percent2;
        mcrPriceHistory.PriceUnit              = _basePriceLineMap.PriceUnit;
        mcrPriceHistory.QuantityAmount         = _basePriceLineMap.QuantityAmount;
        mcrPriceHistory.QuantityAmountTo       = _basePriceLineMap.QuantityAmountTo;
        mcrPriceHistory.Relation               = _basePriceLineMap.Relation;
        mcrPriceHistory.UnitId                 = _basePriceLineMap.UnitId;

        mcrPriceHistory.JournalNum             = _basePriceLineMap.JournalNum;
        mcrPriceHistory.PriceComponentCode     = _basePriceLineMap.PriceComponentCode;
        mcrPriceHistory.PriceHistoryType       = MCRPriceHistory::priceType2MCRPriceHistoryType(_basePriceLineMap.Relation);

        if (mcrPriceHistory.validateWrite())
        {
            mcrPriceHistory.insert();
        }
    }

    MCRPriceHistoryRef mcrPriceHistoryRef;

    // Insert a new reference for current sales line and price history
    if (!MCRPriceHistoryRef::exists(mcrPriceHistory.RecId, _salesLine.mcrOrderLine2PriceHistoryRef))
    {
        mcrPriceHistoryRef.clear();
        mcrPriceHistoryRef.PriceHistoryRecId = mcrPriceHistory.RecId;
        mcrPriceHistoryRef.MCROrderLine2PriceHistoryRef = _salesLine.mcrOrderLine2PriceHistoryRef;
        mcrPriceHistoryRef.insert();
    }

    // Delete old reference for current sales line
    GUPPriceDetailsHelper::clearPriceHistory(_salesLine, mcrPriceHistory.RecId);
}

public static void clearPriceHistory(SalesLine _salesLine, RefRecId _priceHistoryRecId = 0)
{
    if (_salesLine.mcrOrderLine2PriceHistoryRef)
    {
        MCRPriceHistoryRef mcrPriceHistoryRef;

        mcrPriceHistoryRef.clear();
        mcrPriceHistoryRef.selectForUpdate(true);

        select firstonly mcrPriceHistoryRef
            where mcrPriceHistoryRef.mcrOrderLine2PriceHistoryRef == _salesLine.mcrOrderLine2PriceHistoryRef
                && (!_priceHistoryRecId || mcrPriceHistoryRef.PriceHistoryRecId != _priceHistoryRecId);
        if (mcrPriceHistoryRef)
        {
            mcrPriceHistoryRef.delete();
        }
    }
}
